// Normalize the Telegram update into a clean, predictable shape.
// ACCESS CONTROL: only these Telegram chat IDs may use the bot.
// Replace the placeholder(s) with your approved chat IDs, or set the
// environment variable ALLOWED_TELEGRAM_CHAT_IDS="111,222" to override.
const ALLOWED_TELEGRAM_CHAT_IDS = ['REPLACE_WITH_APPROVED_CHAT_ID'];

function fromEnv() {
  try {
    const raw = $env && $env.ALLOWED_TELEGRAM_CHAT_IDS;
    if (raw) return String(raw).split(',').map(s => s.trim()).filter(Boolean);
  } catch (e) {}
  return null;
}
const allowed = fromEnv() || ALLOWED_TELEGRAM_CHAT_IDS;

const payload = items[0].json || {};
const msg = payload.message || payload.edited_message || payload.channel_post || {};
const chat = msg.chat || {};
const from = msg.from || {};

const text = msg.text || msg.caption || '';
let messageType = 'text';
if (msg.document) messageType = 'document';
else if (msg.photo) messageType = 'photo';
else if (msg.video) messageType = 'video';
else if (msg.voice) messageType = 'voice';
else if (!msg.text && msg.caption) messageType = 'caption';

const telegramChatId = String(chat.id !== undefined ? chat.id : '');
const langCode = String(from.language_code || '').toLowerCase();
const languageHint = langCode.startsWith('de') ? 'de' : (langCode.startsWith('en') ? 'en' : 'auto');

const isAllowed = allowed.map(String).includes(telegramChatId);

return [{
  json: {
    platform: 'telegram',
    telegramChatId,
    telegramUserId: String(from.id !== undefined ? from.id : ''),
    telegramUserName: from.username || from.first_name || '',
    telegramMessageId: String(msg.message_id !== undefined ? msg.message_id : ''),
    chatInput: String(text || ''),
    messageType,
    languageHint,
    isAllowed,
    originalPayload: payload,
  },
}];

// Clean the AI agent output before sending it to Telegram.
const j = items[0].json || {};
let text = j.output;
if (text === undefined || text === null) text = j.finalReply || j.text || '';
text = String(text);

// 1. Remove accidental leading equals signs (the double-equals expression bug class).
text = text.replace(/^\s*=+\s*/, '');
// 2. Remove literal undefined/null tokens.
text = text.replace(/\b(undefined|null)\b/g, '').replace(/[ \t]{2,}/g, ' ');
// 3. Remove any leaked n8n branding / attribution.
text = text.replace(/this message was sent automatically with n8n.*/gi, '');
text = text.replace(/sent (?:automatically )?(?:with|via|using) n8n/gi, '');
text = text.replace(/\bn8n\b/gi, '');
// 4. Strip obvious debug JSON wrappers if the whole message is JSON.
const trimmed = text.trim();
if ((trimmed.startsWith('{') && trimmed.endsWith('}')) || (trimmed.startsWith('[') && trimmed.endsWith(']'))) {
  try { const parsed = JSON.parse(trimmed); if (parsed && (parsed.response || parsed.output)) text = String(parsed.response || parsed.output); } catch (e) {}
}
// 5. Collapse excessive blank lines.
text = text.replace(/\n{3,}/g, '\n\n').trim();
if (!text) text = 'I could not produce a reply. Please rephrase your request.';

const chatId = $('Telegram Input Mapper').item.json.telegramChatId;
return [{ json: { finalReply: text, chatId, telegramChatId: chatId } }];

// Split long replies into Telegram-safe chunks (max ~4000 chars),
// never cutting a numbered list line in the middle.
const MAX = 3900;
const j = items[0].json || {};
const chatId = j.chatId || j.telegramChatId;
const text = String(j.finalReply || '');

function flush(buf, out) { if (buf.trim().length) out.push(buf.replace(/\n+$/,'')); }

const lines = text.split('\n');
const chunks = [];
let buf = '';
for (const line of lines) {
  if ((buf + line + '\n').length > MAX) {
    if (buf.trim().length) { flush(buf, chunks); buf = ''; }
    if ((line + '\n').length > MAX) {
      // Hard-wrap a single very long line on word boundaries.
      let rest = line;
      while (rest.length > MAX) {
        let cut = rest.lastIndexOf(' ', MAX);
        if (cut < MAX * 0.6) cut = MAX;
        chunks.push(rest.slice(0, cut));
        rest = rest.slice(cut).trimStart();
      }
      buf = rest + '\n';
      continue;
    }
  }
  buf += line + '\n';
}
flush(buf, chunks);
if (chunks.length === 0) chunks.push(text || ' ');

return chunks.map((chunk, idx) => ({ json: { chunk, chatId, part: idx + 1, totalParts: chunks.length } }));

// Build a clean, user-friendly error message (no raw stack dumps).
const chatId = $('Telegram Input Mapper').item.json.telegramChatId;
let msg = 'Something went wrong while processing your request.';
try {
  const j = items[0].json || {};
  const e = j.error || (j.json && j.json.error);
  if (e && (e.message || e.description)) msg = String(e.message || e.description);
} catch (err) {}
msg = msg.replace(/\bn8n\b/gi, '').trim();
const finalReply = 'Tool failed: Yes\n' +
  'Error message: ' + msg + '\n' +
  'Action taken: None\n' +
  'Verification status: Failed';
return [{ json: { finalReply, chatId, chunk: finalReply } }];

// Lightweight execution logger. Records a compact line per delivered reply.
const j = items[0].json || {};
console.log('[030-AI-ASSISTANT]', JSON.stringify({
  ts: new Date().toISOString(),
  chatId: j.chatId || j.telegramChatId || '',
  part: j.part || 1,
  totalParts: j.totalParts || 1,
}));
return items;
